            if 0.5 <= y_reported <= 2.5:
                state["phase"] = "HOLD"
            else:
                # Continue escaping
                pass
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp
        # Ensure y is within [0.5, 2.5]
        if not (0.5 <= y_reported <= 2.5):
            state["phase"] = "ESCAPE"

    # Track impulse
    current_impulse = MEM.data["impulse"]
    new_impulse = current_impulse + fx * TIME_STEP
    if new_impulse > 60.0:
        # Do not apply the force
        fx = 0.0
        fy = 0.0
