            "vy": 0.0,
            "unlock_steps": 0,
            "unlock_valid": False,
            "hold_steps": 0,
            "hold_valid": False,
            "impulse": 0.0
        }
    state = MEM.data["initial_state"]
    pd = sandbox.get_agent_position()
    x_reported, y_reported = pd[0], pd[1]
    dt = TIME_STEP
    vx_p, vy_p = sandbox.get_agent_velocity()
    state["vx"] = vx_p
    state["vy"] = vy_p
    state["lx"], state["ly"] = x_reported, y_reported
    vxd, vyd = state["vx"], state["vy"]
    ty, w_comp = 1.5, _weight_comp(sandbox)

    front, up, down = sandbox.get_whisker_readings()

    if state["phase"] == "APPROACH":
        # Apply forward force to move into activation zone
        fx = 30.0 if x_reported < 5.0 else 10.0 * (7.0 - x_reported) - 5.0 * vxd
        fy = 50.0 * (ty - y_reported) - 20.0 * vyd + w_comp

        # Adjust vertical force based on whisker readings
        if up < 0.5:
            fy -= 10.0  # Avoid ceiling
        elif down < 0.5:
            fy += 10.0  # Avoid floor

        # Check if in activation zone
        if 5.0 <= x_reported <= 10.0:
            state["phase"] = "UNLOCK"

    elif state["phase"] == "UNLOCK":
        # Apply strict backward force for unlocking
        fx_cmd = -35.0  # Strictly below threshold
        fy_cmd = 50.0 * (ty - y_reported) - 20.0 * vyd + w_comp

        # Adjust vertical force based on whisker readings
        if up < 0.5:
            fy_cmd -= 10.0
        elif down < 0.5:
            fy_cmd += 10.0

        # Check speed condition
        spd = math.hypot(vx_p, vy_p)
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p

        # Check unlock conditions
        activation_zone = (5.0 <= x_reported <= 10.0)
        fx_valid = (fx_cmd < -34.0)
        speed_valid = (spd < 100.0)
        unlock_valid = activation_zone and fx_valid and speed_valid
        if unlock_valid:
            state["unlock_steps"] += 1
        else:
            state["unlock_steps"] = 0
        if state["unlock_steps"] >= 5:
            state["phase"] = "ESCAPE"
        fx, fy = fx_cmd, fy_cmd

    elif state["phase"] == "ESCAPE":
        # Apply forward force to escape
        fx = 15.0
        fy = 50.0 * (ty - y_reported) - 20.0 * vyd + w_comp

        # Adjust vertical force based on whisker readings
        if up < 0.5:
            fy -= 10.0
        elif down < 0.5:
            fy += 10.0

        # Check if in exit zone
        if x_reported >= _exit_x_min(sandbox):
            if 0.5 <= y_reported <= 2.5:
                state["phase"] = "HOLD"

    elif state["phase"] == "HOLD":
        # Ensure y is within [0.5, 2.5] using whisker data
        x_reported = pd[0]
        y_reported = pd[1]
        if 15.0 <= x_reported and 0.5 <= y_reported <= 2.5:
            state["hold_valid"] = True
        else:
            state["hold_valid"] = False

        if state["hold_valid"]:
            state["hold_steps"] += 1
        else:
            state["hold_steps"] = 0

        # Adjust vertical force based on whisker readings
        fy = 50.0 * (ty - y_reported) - 20.0 * vyd + w_comp
        if up < 0.5:
            fy -= 10.0
        elif down < 0.5:
            fy += 10.0

        # Apply no horizontal force during hold
        fx, fy = 0.0, fy

    # Track impulse
    current_impulse = state["impulse"]
    new_impulse = current_impulse + fx * TIME_STEP
    if new_impulse >= 60.0:
        # Do not apply the force
        sandbox.apply_agent_force(0.0, 0.0)
    else:
        # Apply the force and update impulse
        sandbox.apply_agent_force(fx, fy)
        state["impulse"] = new_impulse
